29	     * Builds {@code <REGION><FY><HASH8><CHK>} from its parts, computing the Luhn check digit over the
30	     * digits of {@code <REGION><FY><HASH8>}.
31	     */
32	    public static String of(String region, String fy2, String hash8) {
33	        String base = region + fy2 + hash8;
34	        return base + luhnCheckDigit(base);
35	    }
36	
37	    /**
38	     * The {@code REGION} segment of {@code memberId}: its leading run of upper-case letters (the FY
39	     * segment begins at the first digit). Returns {@code null} when {@code memberId} is null or has
40	     * no leading letters.
41	     */
42	    public static String region(String memberId) {
43	        if (memberId == null) {
44	            return null;
45	        }
46	        int i = 0;
47	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
48	            i++;
49	        }
50	        return i == 0 ? null : memberId.substring(0, i);
51	    }
52	
53	    /**
54	     * The 2-digit {@code FY} segment of {@code memberId}, immediately after the region. Returns
55	     * {@code null} when {@code memberId} is null or too short to hold a fiscal year.
56	     */
57	    public static String fiscalYear2(String memberId) {
58	        String region = region(memberId);
59	        if (region == null) {
60	            return null;
61	        }
62	        int start = region.length();
63	        if (memberId.length() < start + 2) {
64	            return null;
65	        }
66	        return memberId.substring(start, start + 2);
67	    }
68	
69	    /**
70	     * The single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
71	     * characters are ignored; from the rightmost digit leftwards every second digit is doubled
72	     * (subtracting 9 when the result exceeds 9), and the check digit is {@code (10 - (sum % 10)) % 10}.
73	     */
74	    public static int luhnCheckDigit(String value) {
75	        if (value == null) {
76	            return 0;
77	        }
78	        int sum = 0;
79	        boolean dbl = true;
80	        for (int i = value.length() - 1; i >= 0; i--) {
81	            char c = value.charAt(i);
82	            if (c < '0' || c > '9') {
83	                continue;
84	            }
85	            int d = c - '0';
86	            if (dbl) {
87	                d *= 2;
88	                if (d > 9) {
89	                    d -= 9;
90	                }
91	            }
92	            sum += d;
93	            dbl = !dbl;
94	        }
95	        return (10 - (sum % 10)) % 10;
96	    }
97	}
