11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} (see
16	 * {@link MemberId}): REGION is the region code derived from the postcode/city (see
17	 * {@link OwnerRegion}); FY is the 2-digit fiscal year of the business-day-adjusted
18	 * {@code registrationDate} (the same {@code YY} as the owner's {@code fiscalYear}); HASH8 is the
19	 * first 8 upper-case hex characters of SHA-256 over the normalized telephone concatenated with the
20	 * last name; and CHK is a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}
21	 * (e.g. {@code NSW261A2B3C4D5}). There are no per-city sequence numbers.
22	 *
23	 * <p>Runs after {@link BuildOwner} (so the normalized telephone, last name, postcode and
24	 * registration date are on the owner) and before {@link SaveOwner}. The audit record, the derived
25	 * locality/region and the owner segment all read this identity.
26	 *
27	 * <p>If the computed memberId collides with an existing owner's {@code memberId}, it is
28	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it
29	 * unique.
30	 */
31	public class AssignMemberId {
32	
33	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
34	        String region = OwnerRegion.fromPostcodeOrCity(owner.getPostcode(), owner.getCity());
35	        String fy2 = String.format("%02d", FiscalYear.startYear(owner.getRegistrationDate()) % 100);
36	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
37	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
38	        String base = MemberId.of(region, fy2, hash8(telephone + lastName));
39	        owner.setMemberId(deDuplicate(base, owner, ownerRepository));
40	    }
41	
42	    /**
43	     * Returns {@code base} if no existing owner already uses it, otherwise {@code base-<n>} with the
44	     * smallest {@code n >= 2} that is not already taken by an existing owner.
45	     */
46	    private static String deDuplicate(String base, Owner owner, OwnerRepository ownerRepository) {
47	        Set<String> taken = new HashSet<>();
48	        for (Owner existing : ownerRepository.findAll()) {
49	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
50	                continue; // never compare the new owner against itself
51	            }
52	            String memberId = existing.getMemberId();
53	            if (memberId != null) {
54	                taken.add(memberId);
55	            }
56	        }
57	        if (!taken.contains(base)) {
58	            return base;
59	        }
60	        for (int n = 2; ; n++) {
61	            String candidate = base + "-" + n;
62	            if (!taken.contains(candidate)) {
63	                return candidate;
64	            }
65	        }
66	    }
67	
68	    /** First 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
69	    private static String hash8(String value) {
70	        try {
71	            byte[] digest = MessageDigest.getInstance("SHA-256")
72	                    .digest(value.getBytes(StandardCharsets.UTF_8));
73	            StringBuilder sb = new StringBuilder(16);
74	            for (int i = 0; i < 4; i++) {
75	                sb.append(String.format("%02X", digest[i]));
76	            }
77	            return sb.toString();
78	        }
79	        catch (NoSuchAlgorithmException e) {
80	            throw new IllegalStateException("SHA-256 not available", e);
81	        }
82	    }
83	}
