1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft (possible) duplicate. An owner whose WHOLE {@link OwnerIdentity#identityKey
10	 * identityKey} differs from every existing owner's (so it is not a hard duplicate — that check
11	 * runs earlier and rejects with 409) but that shares an existing owner's last-name
12	 * {@link Soundex} code and {@code postcode} is still created, with {@code possibleDuplicate} set
13	 * true and {@code possibleDuplicateOf} set to the matching owner's id. When several owners match,
14	 * the earliest (lowest id) is chosen. Otherwise {@code possibleDuplicate} is false and
15	 * {@code possibleDuplicateOf} is absent.
16	 *
17	 * <p>A declared household member — the request set {@code sharesHousehold} true — is not a
18	 * suspected duplicate, so it is never flagged.
19	 *
20	 * <p>Runs before {@link SaveOwner}, so the new owner is not yet persisted and only pre-existing
21	 * owners are considered.
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
26	            OwnerRepository ownerRepository) {
27	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
28	            owner.setPossibleDuplicate(false);
29	            owner.setPossibleDuplicateOf(null);
30	            return; // a declared household member is not a suspected duplicate
31	        }
32	        String soundex = Soundex.of(owner.getLastName());
33	        String postcode = owner.getPostcode();
34	        String key = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(),
35	                owner.getLastName());
36	        Integer matchId = null;
37	        if (postcode != null && !postcode.isBlank() && !soundex.isEmpty()) {
38	            for (Owner existing : ownerRepository.findAll()) {
39	                if (existing.getId() == null || existing.getId().equals(owner.getId())) {
40	                    continue; // never match the new owner against itself
41	                }
42	                if (Boolean.TRUE.equals(existing.getDeleted())) {
43	                    continue; // a soft-deleted owner is not a possible duplicate
44	                }
45	                String other = OwnerIdentity.identityKey(existing.getTelephone(),
46	                        existing.getEmail(), existing.getLastName());
47	                if (!key.equals(other)
48	                        && soundex.equals(Soundex.of(existing.getLastName()))
49	                        && postcode.equals(existing.getPostcode())) {
50	                    if (matchId == null || existing.getId() < matchId) {
51	                        matchId = existing.getId();
52	                    }
53	                }
54	            }
55	        }
56	        owner.setPossibleDuplicate(matchId != null);
57	        owner.setPossibleDuplicateOf(matchId);
58	    }
59	}
